## Analyzes the extended Sentinel-3 time series (May-2018 to June-2026,
## ~8 years) generated by download_extended_Sentinel3_series.py: recomputes
## seasonality/interannual trend with more years (to confirm the
## findings of the 2023-2026 series), and compares blooms near
## the dam vs. the whole reservoir.
##
## Input:
##   - tablas/Sentinel3_serie_temporal_extendida.csv
## Output:
##   - figuras/Sentinel3_serie_temporal_extendida.png
##   - figuras/Sentinel3_estacionalidad_extendida.png
##   - figuras/Sentinel3_cortina_vs_embalse.png
##   - tablas/Sentinel3_resumen_anual_extendido.csv
##   - tablas/Sentinel3_cortina_vs_embalse_resumen.csv

library(dplyr)
library(ggplot2)
library(lubridate)

BASE <- "/home/jf/pCloudDrive/trabajos/PresaSolis"
serie <- read.csv(file.path(BASE, "tablas/Sentinel3_serie_temporal_extendida.csv")) %>%
  mutate(fecha = as.Date(fecha))

cat("Total dates downloaded:", nrow(serie), "\n")
cat("Range:", as.character(min(serie$fecha)), "to", as.character(max(serie$fecha)), "\n\n")

UMBRAL_COBERTURA <- 0.10

## ============================================================
## 1) WHOLE RESERVOIR -- recomputed with 8 years instead of 3
## ============================================================
embalse_ok <- serie %>% filter(!is.na(embalse_frac_validos), embalse_frac_validos >= UMBRAL_COBERTURA)
cat("=== WHOLE RESERVOIR ===\n")
cat("Dates used (coverage >=10%):", nrow(embalse_ok), "of", nrow(serie), "\n")
cat("Median CHL_NN range:", round(min(embalse_ok$embalse_chl_nn_mediana,na.rm=TRUE),1), "-",
    round(max(embalse_ok$embalse_chl_nn_mediana,na.rm=TRUE),1), "ug/L\n")
cat("Overall median:", round(median(embalse_ok$embalse_chl_nn_mediana,na.rm=TRUE),1), "ug/L\n")

fechas_campo <- as.Date(c("2024-06-03", "2024-09-21"))

p1 <- ggplot(embalse_ok, aes(x = fecha)) +
  geom_ribbon(aes(ymin = embalse_chl_nn_p10, ymax = embalse_chl_nn_p90), fill = "#0EA5A4", alpha = 0.10) +
  geom_ribbon(aes(ymin = embalse_chl_nn_p25, ymax = embalse_chl_nn_p75), fill = "#0EA5A4", alpha = 0.24) +
  geom_line(aes(y = embalse_chl_nn_mediana), color = "#0B7285", linewidth = 0.35) +
  geom_point(aes(y = embalse_chl_nn_mediana, color = satelite), size = 0.8, alpha = 0.6) +
  geom_vline(xintercept = fechas_campo, linetype = "dashed", color = "grey30") +
  scale_color_manual(values = c(S3A = "#D97706", S3B = "#7C3AED")) +
  labs(x = NULL, y = "Clorofila-a CHL_NN (µg/L)", color = "Satélite",
       title = "Dinámica de clorofila en la Presa Solís, serie extendida (2018-2026)",
       subtitle = sprintf("Mediana + percentiles 25-75%%/10-90%% del embalse completo. n=%d fechas.", nrow(embalse_ok))) +
  theme_bw(base_size = 11) + theme(legend.position = "bottom")

dir.create(file.path(BASE, "figuras"), showWarnings = FALSE)
ggsave(file.path(BASE, "figuras/Sentinel3_serie_temporal_extendida.png"), p1, width = 13, height = 5, dpi = 150)
cat("Written: figuras/Sentinel3_serie_temporal_extendida.png\n")

MESES_EN <- c("Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec")
embalse_ok$mes <- factor(MESES_EN[month(embalse_ok$fecha)], levels = MESES_EN)

p2 <- ggplot(embalse_ok, aes(x = mes, y = embalse_chl_nn_mediana)) +
  geom_boxplot(fill = "#0EA5A4", alpha = 0.4, outlier.size = 0.6) +
  labs(x = NULL, y = "CHL_NN mediana por fecha (µg/L)",
       title = "Estacionalidad de clorofila, serie extendida 2018-2026",
       subtitle = sprintf("n=%d fechas, 8 anios combinados", nrow(embalse_ok))) +
  theme_bw(base_size = 11)
ggsave(file.path(BASE, "figuras/Sentinel3_estacionalidad_extendida.png"), p2, width = 9, height = 5, dpi = 150)
cat("Written: figuras/Sentinel3_estacionalidad_extendida.png\n")

## interannual trend
embalse_ok$anio <- year(embalse_ok$fecha)
resumen_anual <- embalse_ok %>% group_by(anio) %>%
  summarise(n = n(), mediana = median(embalse_chl_nn_mediana, na.rm=TRUE),
            area_floracion_mediana = median(embalse_area_floracion_km2, na.rm=TRUE),
            area_floracion_max = max(embalse_area_floracion_km2, na.rm=TRUE))
cat("\n--- Interannual trend (whole reservoir, extended series) ---\n")
print(resumen_anual)
write.csv(resumen_anual, file.path(BASE, "tablas/Sentinel3_resumen_anual_extendido.csv"), row.names = FALSE)

## trend test (simple Mann-Kendall via cor.test against the time rank)
mk <- cor.test(as.numeric(embalse_ok$fecha), embalse_ok$embalse_chl_nn_mediana, method = "kendall")
cat("\n--- Kendall trend test (whole period, not just annual medians) ---\n")
cat("tau =", round(mk$estimate,3), " p =", format.pval(mk$p.value,digits=3), "\n")

## dry/rainy t-test with more data
embalse_ok$temporada <- ifelse(month(embalse_ok$fecha) %in% 5:10, "Lluvias (may-oct)", "Secas (nov-abr)")
tt <- t.test(embalse_chl_nn_mediana ~ temporada, data = embalse_ok)
cat("\n--- Dry/rainy t-test, extended series ---\n")
print(tt)

## ============================================================
## 2) NEAR THE DAM vs. WHOLE RESERVOIR (same dates)
## ============================================================
cat("\n\n=== NEAR THE DAM vs. WHOLE RESERVOIR ===\n")
ambos_ok <- serie %>%
  filter(!is.na(embalse_frac_validos), embalse_frac_validos >= UMBRAL_COBERTURA,
         !is.na(cortina_frac_validos), cortina_frac_validos >= UMBRAL_COBERTURA)
cat("Dates with sufficient coverage in BOTH regions:", nrow(ambos_ok), "\n")

cat("\nMedian CHL_NN -- reservoir vs. near-dam:\n")
cat("  Reservoir: median =", round(median(ambos_ok$embalse_chl_nn_mediana,na.rm=TRUE),1),
    " (range", round(min(ambos_ok$embalse_chl_nn_mediana,na.rm=TRUE),1), "-",
    round(max(ambos_ok$embalse_chl_nn_mediana,na.rm=TRUE),1), ")\n")
cat("  Near-dam: median =", round(median(ambos_ok$cortina_chl_nn_mediana,na.rm=TRUE),1),
    " (range", round(min(ambos_ok$cortina_chl_nn_mediana,na.rm=TRUE),1), "-",
    round(max(ambos_ok$cortina_chl_nn_mediana,na.rm=TRUE),1), ")\n")

wt <- wilcox.test(ambos_ok$cortina_chl_nn_mediana, ambos_ok$embalse_chl_nn_mediana, paired = TRUE)
cat("  Paired Wilcoxon test (same date, near-dam vs. reservoir): p =", format.pval(wt$p.value, digits=3), "\n")

cat("\nBloom frequency (area>0) -- reservoir:",
    round(100*mean(ambos_ok$embalse_area_floracion_km2>0, na.rm=TRUE),1), "% of dates;  near-dam:",
    round(100*mean(ambos_ok$cortina_area_floracion_km2>0, na.rm=TRUE),1), "% of dates\n")

## fraction of the bloom area attributable to the near-dam region (proxy for "how much worse it gets near the dam")
ambos_ok$frac_floracion_relativa <- ambos_ok$cortina_frac_floracion - ambos_ok$embalse_frac_floracion
cat("Median difference in bloom fraction (near-dam - reservoir):",
    round(median(ambos_ok$frac_floracion_relativa, na.rm=TRUE),3), "\n")

## comparative plot
comp_long <- bind_rows(
  ambos_ok %>% transmute(fecha, region="Embalse completo", chl_nn = embalse_chl_nn_mediana),
  ambos_ok %>% transmute(fecha, region="Cerca de la cortina", chl_nn = cortina_chl_nn_mediana)
)
p3 <- ggplot(comp_long, aes(x = fecha, y = chl_nn, color = region)) +
  geom_line(alpha=0.6, linewidth=0.3) +
  geom_point(size=0.6, alpha=0.5) +
  scale_color_manual(values = c("Embalse completo"="#0EA5A4", "Cerca de la cortina"="#D97706")) +
  labs(x=NULL, y="CHL_NN mediana (µg/L)", color=NULL,
       title="Clorofila cerca de la cortina vs. embalse completo",
       subtitle = sprintf("n=%d fechas con cobertura suficiente en ambas regiones", nrow(ambos_ok))) +
  theme_bw(base_size=11) + theme(legend.position="bottom")
ggsave(file.path(BASE, "figuras/Sentinel3_cortina_vs_embalse.png"), p3, width=13, height=5, dpi=150)
cat("\nWritten: figuras/Sentinel3_cortina_vs_embalse.png\n")

resumen_comparacion <- ambos_ok %>%
  summarise(
    n = n(),
    embalse_mediana = median(embalse_chl_nn_mediana, na.rm=TRUE),
    cortina_mediana = median(cortina_chl_nn_mediana, na.rm=TRUE),
    embalse_pct_fechas_floracion = 100*mean(embalse_area_floracion_km2>0, na.rm=TRUE),
    cortina_pct_fechas_floracion = 100*mean(cortina_area_floracion_km2>0, na.rm=TRUE),
    wilcoxon_p = wt$p.value
  )
write.csv(resumen_comparacion, file.path(BASE, "tablas/Sentinel3_cortina_vs_embalse_resumen.csv"), row.names = FALSE)
cat("Written: tablas/Sentinel3_cortina_vs_embalse_resumen.csv\n")
print(resumen_comparacion)
